CREATE TABLE IF NOT EXISTS programs(id SERIAL PRIMARY KEY,name TEXT NOT NULL,weeks INT NOT NULL,level TEXT NOT NULL,price NUMERIC(10,2) NOT NULL,accent TEXT DEFAULT 'lime',summary TEXT,active BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS booking_slots(id SERIAL PRIMARY KEY,starts_at TIMESTAMPTZ NOT NULL,booked BOOLEAN DEFAULT false);
CREATE TABLE IF NOT EXISTS bookings(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,program_id INT,slot_label TEXT NOT NULL,goal TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
